    27	int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    28	{
    29	        gnutls_datum_t raw = {(unsigned char*)data, (unsigned int)size};
    30	        gnutls_pkcs12_t p12;
    31	        gnutls_x509_privkey_t key;
    32	        gnutls_x509_crt_t *chain;
    33	        gnutls_x509_crt_t *extras;
    34	        gnutls_x509_crl_t crl;
    35	        unsigned int chain_len = 0, extras_len = 0;
    36	        int ret;
    37	
    38	        raw.data = (unsigned char *)data;
    39	        raw.size = size;
    40	
    41	        ret = gnutls_pkcs12_init(&p12);
    42	        assert(ret >= 0);
    43	
    44	        ret = gnutls_pkcs12_import(p12, &raw, GNUTLS_X509_FMT_DER, 0);
    45	        if (ret < 0) {
    46	                goto cleanup;
    47	        }
    48	
    49	        /* catch crashes */
    50	        gnutls_pkcs12_verify_mac(p12, "1234");
    51	
    52	        ret = gnutls_pkcs12_simple_parse(p12, "1234", &key, &chain, &chain_len, &extras, &extras_len, &crl, 0);
    53	        if (ret >= 0) {
    54	                gnutls_x509_privkey_deinit(key);
    55	                if (crl)
    56	                        gnutls_x509_crl_deinit(crl);
    57	                if (extras_len > 0) {
    58	                        for (unsigned i = 0; i < extras_len; i++)
    59	                                gnutls_x509_crt_deinit(extras[i]);
    60	                        gnutls_free(extras);
    61	                }
    62	                if (chain_len > 0) {
    63	                        for (unsigned i = 0; i < chain_len; i++)
    64	                                gnutls_x509_crt_deinit(chain[i]);
    65	                        gnutls_free(chain);
    66	                }
    67	        }
    68	
    69	cleanup:
    70	        gnutls_pkcs12_deinit(p12);
    71	        return 0;
    72	}
